"""Explain terminators and KMSAN origin record shapes using small examples."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1833': ('128칸짜리 이름표에는 이름만 꽉 채우지 않아요. 여기가 끝이라는 표시를 넣을 한 칸도 필요해요.', '문자열의 내용과 끝 표시가 차지하는 공간을 계산합니다.', '네 칸짜리 작은 모형에 a, b, c, 끝 표시 0을 넣고 내용은 세 칸임을 확인하세요.', ['pretty_descr는 변수 설명을 읽기 좋은 이름으로 바꾸는 함수예요. 결과를 담는 report_local_descr는 128바이트 배열이에요. 바이트는 메모리 크기를 세는 단위이고, 여기서 예로 드는 영문자는 한 글자에 한 바이트를 써요.', 'C 문자열은 마지막에 값이 0인 바이트를 두어 끝을 알려요. 이것은 눈에 보이는 숫자 글자 0과 달라요. 그래서 128칸에 내용은 최대 127바이트, 끝 표시는 1바이트를 넣어요. 여러 바이트를 쓰는 한글도 항상 127글자 들어간다는 뜻은 아니에요.', 'pos는 결과를 쓸 칸 번호예요. 칸 번호는 0부터 시작해 마지막이 127이에요. 원문은 먼저 글자를 쓰고 pos + 1이 128인지 확인해요. pos가 127이면 반복을 끝낸 뒤 같은 칸에 끝 표시 0을 써서 방금 쓴 글자를 덮어요.', '따라서 내용이 아무리 길어도 최종 문자열 내용은 0번부터 126번까지예요. 네 칸 모형에서 a, b, c, d를 쓰려 하면 마지막 d 자리에는 끝 표시가 들어가 최종 내용은 abc가 되는 것과 같아요.', '입력이 @function이면 첫 글자 @에서 바로 멈춰요. 아직 pos는 0이므로 결과의 0번 칸에 끝 표시를 써요. 처음부터 끝 표시가 나오니 현재 문자열은 빈 문자열이에요.', '이전 호출의 글자가 뒤쪽 칸에 남아 있어도 현재 문자열은 첫 끝 표시까지만 읽어요. 모든 칸을 지우지 않아도 짧은 새 문자열을 나타낼 수 있어요. 다만 뒤쪽 메모리까지 실제로 지워졌다는 뜻은 아니에요.'], [('128바이트 배열에 끝 표시까지 넣으면 영문 내용은 최대 몇 바이트인가요?', ['내용 128바이트와 배열 밖 끝 표시를 넣어요', '내용 127바이트와 끝 표시 1바이트를 넣어요'], '정답은 두 번째예요. 끝 표시도 배열 안에 있어야 해요. 128 - 1 = 127이므로 영문 한 바이트 문자로 된 내용은 최대 127글자예요.'), ('입력이 @function이면 결과 문자열은 무엇인가요?', ['빈 문자열이에요', 'function 전체예요'], '정답은 첫 번째예요. @에서 바로 멈추고 0번 칸에 끝 표시를 써요. 뒤에 예전 글자가 남아 있더라도 현재 문자열의 내용으로 읽지 않아요.')]), 'os1834': ('보관함 번호가 없는 경우와 번호로 찾아봤지만 기록을 얻지 못한 경우는 달라요. 이 함수도 두 상황을 다르게 처리해요.', '원인 기록 번호가 없는 경우와 조회 결과가 빈 경우를 구별합니다.', 'origin 0→바로 돌아가기, origin 7·조회 결과 0개→기록 없음 안내라는 두 길을 그리세요. 7은 가상 번호예요.', ['KMSAN은 준비되지 않은 값이 어디서 생겼는지 추적해요. origin은 그런 발생 원인 기록을 찾는 번호이고 handle이라고도 불러요. 번호 자체가 기록 전체를 담은 것은 아니에요. stack depot이라는 보관소에서 번호에 해당하는 호출 경로 기록을 찾아요.', 'kmsan_print_origin은 먼저 origin이 0인지 확인해요. 0이면 이 함수에서는 원인 기록이 없는 것으로 보고 곧바로 돌아가요. 보관소 조회보다 먼저 돌아가므로 이 함수가 stack is not available이라는 문장을 출력하는 것도 아니에요.', 'origin이 0이 아니면 stack_depot_fetch로 조회해요. nr_entries는 얻은 항목 수이고 entries는 그 항목들이 놓인 곳을 가리켜요. 번호가 0인지와 조회한 항목 수가 0인지는 서로 다른 질문이에요.', '조회 항목이 0개이면 첫 항목 entries[0]을 읽지 않고 magic을 0으로 정해요. magic은 기록 종류를 구별하는 표식이에요. 항목 개수와 표식이 맞아야 지역 변수 형식이나 연결 기록 형식으로 읽어요.', '0개인 경우에는 일반 생성 원인 경로로 가서 Uninit was created at:이라는 제목과 stack is not available이라는 안내를 출력해요. 호출 경로 기록을 보여 줄 수 없다는 뜻이에요. 존재하지 않는 지역 변수 설명을 만들어 내지 않아요.', '종이 모형에서 번호 0과 번호 7의 빈 조회 결과를 비교해 보세요. 전자는 이 함수가 아무 출력 없이 돌아가고 후자는 기록이 없다는 안내를 해요. 7은 조건을 이해하는 가상 번호이며 실제 임의 번호를 넣어도 안전하다는 뜻은 아니에요.'], [('origin이 0이면 kmsan_print_origin 자체는 무엇을 출력하나요?', ['언제나 stack is not available을 출력해요', '이 함수에서는 출력 없이 돌아가요'], '정답은 두 번째예요. 첫 return이 보관소 조회보다 앞에 있어요. 번호가 없는 경우와 조회 후 기록이 빈 경우를 같은 것으로 보면 안 돼요.'), ('origin은 0이 아닌데 조회한 항목이 0개라면 어떤 안내가 나오나요?', ['stack is not available이라는 안내가 나와요', '반드시 지역 변수 이름이 나와요'], '정답은 첫 번째예요. 일반 생성 원인 제목 뒤에 경로 기록이 없다는 안내를 해요. 지역 변수 형식에는 필요한 항목 수와 종류 표식이 있어야 하므로 빈 기록을 그 형식으로 읽지 않아요.')]), 'os1835': ('종류표, 이름 주소, 위치 두 곳을 담은 네 칸 카드라고 생각해 봐요. 칸 수와 종류표를 함께 확인해야 각 칸을 바르게 읽을 수 있어요.', '지역 변수 원인 기록의 네 항목과 선택적인 위치 출력을 이해합니다.', '0번 종류표, 1번 설명 주소, 2번 위치 A, 3번 위치 B를 그리세요. B가 없을 때 B 출력만 지우세요.', ['kmsan_print_origin은 원인 기록을 읽어 어디서 값이 생겼는지 설명해요. 지역 변수는 함수 안에서 사용하는 변수예요. 지역 변수 원인 기록은 일반 호출 경로와 다른 네 항목 형식으로 저장될 수 있어요.', '지역 변수 형식으로 읽으려면 nr_entries가 4이고 첫 항목 magic이 KMSAN_ALLOCA_MAGIC_ORIGIN이어야 해요. &&는 두 조건이 모두 맞아야 한다는 뜻이에요. 표식만 같거나 항목 수만 4라는 이유로 이 형식에 들어가지 않아요.', 'C 배열 번호는 0부터 세므로 네 항목의 번호는 0, 1, 2, 3이에요. 0번은 종류표이고 1번은 설명 문자열을 가리키는 주소예요. 2번과 3번은 코드 위치를 나타내는 pc1과 pc2로 읽어요.', '설명은 pretty_descr로 다듬어 지역 변수 이름과 함께 출력해요. 코드 위치는 어느 함수의 어느 부분인지 나타내는 정보예요. 보고 코드는 if (pc1), if (pc2)로 각각 따로 있는지 확인해요.', 'pc1만 있고 pc2가 NULL이면 첫 위치 줄만 출력해요. NULL은 이 자리에서 주소가 없다는 표시예요. 둘 다 없으면 두 위치 줄 모두 생략해요. 이름 설명까지 선택 정보라는 뜻은 아니며 설명 주소는 올바른 기록 형식이라는 전제가 필요해요.', '이 지역 변수 분기의 마지막 break는 반복을 끝내요. 뒤의 연결 기록 분기로 계속 내려가지 않아요. 네 칸 그림에서 조건 확인→설명 출력→있는 위치만 출력→끝 순서로 따라가 보세요.'], [('지역 변수 원인 형식은 종류표와 함께 몇 항목을 요구하나요?', ['3개예요', '4개예요'], '정답은 두 번째예요. 종류표, 설명 주소, 코드 위치 두 개로 네 항목이에요. 세 항목인 연결 기록 형식과 구별하세요. 수만 맞는 것으로 충분하지 않고 종류표도 맞아야 해요.'), ('pc2가 NULL이면 그 위치 줄도 반드시 출력하나요?', ['아니요. pc2가 있는 경우에만 그 줄을 출력해요', '네. 언제나 0번 위치라는 줄을 출력해요'], '정답은 첫 번째예요. if (pc2)가 출력 여부를 정해요. pc1도 별도로 검사하므로 pc2가 없다고 pc1 출력까지 무조건 생략하지는 않아요.')]), 'os1836': ('물건의 배송 기록을 거꾸로 따라가듯, 지금 저장된 곳을 보고 이전 기록으로 이동하며 처음 생긴 곳을 찾아요.', '세 항목으로 연결된 원인 기록을 거꾸로 따라가는 방법을 이해합니다.', '최근 기록 C→이전 기록 B→처음 생성 A를 그리세요. C와 B에서는 저장 위치를, A에서는 생성 위치를 적으세요.', ['값이 만들어진 곳과 나중에 다른 메모리에 저장된 곳은 다를 수 있어요. KMSAN의 연결 원인 기록은 현재 저장 위치와 그 이전 원인을 함께 남겨 두어 경로를 거슬러 설명하도록 도와줘요.', '이 형식은 항목 수가 3이고 첫 표식이 KMSAN_CHAIN_MAGIC_ORIGIN일 때만 선택돼요. entries[0]은 종류표, entries[1]은 현재 저장 시점의 호출 경로 기록 번호, entries[2]는 이전 원인 기록 번호예요.', '코드는 entries[1]을 head에 넣고 entries[2]를 다음에 살펴볼 origin에 넣어요. 현재 데이터의 첫 바이트를 읽어 origin으로 쓰는 것이 아니에요. origin은 발생 원인을 찾아가는 번호예요.', '먼저 저장된 위치라는 제목을 출력하고 head로 현재 저장 시점의 호출 경로를 조회해요. 조회한 경로 배열의 검사 정보를 준비됨으로 표시하고, 앞쪽 검사 도구 내부 기록을 건너뛴 뒤 경로를 출력해요. 이는 사용자의 원래 데이터를 새 값으로 채우는 작업이 아니에요.', '그다음 continue로 반복의 처음으로 돌아가 이전 origin을 조회해요. C→B→A라면 C의 저장 위치, B의 저장 위치, A의 생성 위치 순으로 따라갈 수 있어요. 지역 변수 형식이나 일반 생성 기록을 출력하는 분기에서는 break로 끝나요. 저장 깊이 제한에 걸린 기록은 일부 경로가 생략되었을 수 있다는 안내도 나와요.', '이 while 반복에는 방문한 번호를 모아 같은 번호를 다시 만났는지 검사하는 코드가 없어요. C→B→C처럼 잘못된 고리가 생겨도 이 반복 자체가 자동으로 찾아 끊는다고 설명하면 안 돼요. 정상 저장 규칙에 따른 유한한 기록을 전제로 읽으며, 종이 실습에서는 C→B→A처럼 고리 없는 예를 사용해요.'], [('연결 기록의 entries[2]는 무엇을 뜻하나요?', ['사용자 데이터의 첫 바이트예요', '이전 원인을 찾는 origin 번호예요'], '정답은 두 번째예요. 코드가 origin = entries[2]로 다음 조회 대상을 바꿔요. 현재 저장 위치의 경로 번호인 entries[1]과도 역할이 달라요.'), ('출력 반복 자체에 C→B→C 같은 고리를 찾아 끊는 검사가 있나요?', ['아니요. 이 반복에는 그런 검사가 없어요', '네. 어떤 손상된 연결도 자동으로 찾아 끝내요'], '정답은 첫 번째예요. 이미 방문한 번호 목록이나 중복 확인 조건이 없어요. 정상 기록을 만드는 쪽의 규칙과 출력 반복이 직접 수행하는 검사를 구별해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_454.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
